  `province` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `city` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `postalCode` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `addressLine` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `isDefault` tinyint(1) NOT NULL DEFAULT '0',
  `recipientType` enum('SELF','OTHER') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'SELF',
  `recipientNationalId` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `provinceId` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cityId` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `plaque` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `unit` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `floor` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `latitude` decimal(10,7) DEFAULT NULL,
  `longitude` decimal(10,7) DEFAULT NULL,
