--
-- Table structure for table `mediaasset`
--

DROP TABLE IF EXISTS `mediaasset`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `mediaasset` (
  `id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `type` enum('IMAGE','VIDEO','DOCUMENT') COLLATE utf8mb4_unicode_ci NOT NULL,
  `url` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `storageKey` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `alt` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mimeType` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sizeBytes` int NOT NULL,
  `width` int DEFAULT NULL,
  `height` int DEFAULT NULL,
  `durationSec` int DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `scope` enum('CATEGORY','PRODUCT','HOMEPAGE','BRAND','PRODUCT_BRAND','ARTICLE','ARTICLE_AUTHOR') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PRODUCT',
  `caption` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`id`),
  UNIQUE KEY `MediaAsset_storageKey_key` (`storageKey`),
  KEY `MediaAsset_scope_createdAt_idx` (`scope`,`createdAt`),
  KEY `MediaAsset_scope_type_createdAt_idx` (`scope`,`type`,`createdAt`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

